'use strict';

const Client = require('./src/client');
const { DigitalPayeError } = require('./src/errors');

const Auth = require('./src/resources/auth');
const Orders = require('./src/resources/orders');
const Transactions = require('./src/resources/transactions');
const PaymentLinks = require('./src/resources/paymentLinks');
const Payouts = require('./src/resources/payouts');
const Balance = require('./src/resources/balance');
const Operators = require('./src/resources/operators');
const Customers = require('./src/resources/customers');
const Beneficiaries = require('./src/resources/beneficiaries');
const Invoices = require('./src/resources/invoices');
const BulkTransfers = require('./src/resources/bulkTransfers');
const ScheduledTransfers = require('./src/resources/scheduledTransfers');
const Escrow = require('./src/resources/escrow');
const Contactless = require('./src/resources/contactless');

/**
 * DigitalPaye API client.
 *
 * @example
 *   const DigitalPaye = require('digitalpaye-node');
 *   const dp = new DigitalPaye({ publicKey: 'pub_xxx', secret: 'sk_xxx' });
 *
 *   const order = await dp.orders.create({
 *     currency: 'XOF',
 *     items: [{ name: 'T-shirt', quantity: 2, unit_price: 5000 }],
 *   });
 */
class DigitalPaye {
  /**
   * @param {object} options
   * @param {string} options.publicKey  Your DigitalPaye API public key
   * @param {string} options.secret     Your DigitalPaye API secret key
   * @param {string} [options.baseUrl]  Override the API base URL (advanced/testing use only)
   * @param {number} [options.timeout]  Request timeout in ms (default 30000)
   */
  constructor(options) {
    this.client = new Client(options);

    this.auth = new Auth(this.client);
    this.orders = new Orders(this.client);
    this.transactions = new Transactions(this.client);
    this.paymentLinks = new PaymentLinks(this.client);
    this.payouts = new Payouts(this.client);
    this.balance = new Balance(this.client);
    this.operators = new Operators(this.client);
    this.customers = new Customers(this.client);
    this.beneficiaries = new Beneficiaries(this.client);
    this.invoices = new Invoices(this.client);
    this.bulkTransfers = new BulkTransfers(this.client);
    this.scheduledTransfers = new ScheduledTransfers(this.client);
    this.escrow = new Escrow(this.client);
    this.contactless = new Contactless(this.client);
  }
}

module.exports = DigitalPaye;
module.exports.DigitalPaye = DigitalPaye;
module.exports.DigitalPayeError = DigitalPayeError;
